INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 24, 'theory', 'Квиз: libvirt и virsh');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 0, 'Какой адрес подключает virsh к системному экземпляру, который ведёт гостей всех пользователей?', '["qemu:///session", "qemu+ssh://localhost/session", "qemu:///system", "libvirt:///root"]', 2, 'qemu:///system — системный экземпляр, он работает от root и ведёт гостей всех пользователей. qemu:///session — личный экземпляр обычного пользователя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 1, 'Что делает virsh destroy web01?', '["Принудительно останавливает гостя, не трогая диски и описание", "Удаляет описание домена и его диски", "Просит гостя корректно выключиться через ACPI", "Приостанавливает гостя в памяти"]', 0, 'destroy выдёргивает питание: гость не успевает среагировать, но тома не удаляются, а постоянный домен можно запустить снова. Вежливая просьба — это shutdown.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 2, 'В XML домена записано <memory>2097152</memory> без атрибута unit. Сколько памяти это значит?', '["Два мебибайта", "2097152 мебибайт", "Два миллиона байт", "Два гибибайта, потому что единица по умолчанию — кибибайт"]', 3, 'Без unit число читается в кибибайтах: 2097152 КиБ = 2048 МиБ = 2 ГиБ. Поэтому в скриптах единицу переводят явно.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 3, 'Что нужно сиду NoCloud, чтобы cloud-init его нашёл и принял за первую загрузку?', '["Диск с любой меткой и файл config.yaml", "Файловая система с меткой cidata и файл meta-data с instance-id", "Только user-data: meta-data гость создаст сам", "Сетевая карта с именем cloud0"]', 1, 'Нужна файловая система vfat или ISO с меткой cidata, файлы лежат в корне, а в meta-data есть instance-id: по нему определяют первую загрузку. Сменив instance-id, получают повторную настройку.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 24, 4, 'Что будет, если удалить снимок, у которого есть потомки, командой snapshot-delete без дополнительных ключей?', '["Удалятся все потомки", "Команда откажется, пока есть потомки", "Изменения снимка вольются в потомков", "Домен откатится к родителю"]', 2, 'Без --children изменения удаляемого снимка вливаются в его потомков, а те становятся детьми его родителя. Чтобы убрать ветку целиком, нужен --children.');
